// Applications still at 'Applied' with no reply after N days → mark No Response.
const days = Number($('Config').first().json.noResponseAfterDays) || 21;
const cutoff = Date.now() - days * 86400000;
const out = [];
for (const pg of ($input.first().json.results || [])) {
  const p = pg.properties || {};
  const status = p['Status']?.select?.name || '';
  const applied = p['Applied Date']?.date?.start;
  const lastReply = p['Last Reply Date']?.date?.start;
  if (status === 'Applied' && applied && !lastReply && new Date(applied).getTime() < cutoff) {
    out.push({ json: { pageId: pg.id } });
  }
}
return out;

// Weekly pipeline summary for Discord.
const cfg = $('Config').first().json;
const days = Number(cfg.noResponseAfterDays) || 21;
const cutoff = Date.now() - days * 86400000;
const weekAgo = Date.now() - 7 * 86400000;
const txt = p => !p ? '' : (p.title || p.rich_text || []).map(t => t.plain_text).join('').trim();

const counts = {};
const active = [];
const review = [];
let newThisWeek = 0;
let ghosted = 0;
for (const pg of ($input.first().json.results || [])) {
  const p = pg.properties || {};
  let status = p['Status']?.select?.name || 'Applied';
  const applied = p['Applied Date']?.date?.start;
  const lastReply = p['Last Reply Date']?.date?.start;
  if (status === 'Applied' && applied && !lastReply && new Date(applied).getTime() < cutoff) { status = 'No Response'; ghosted++; }
  counts[status] = (counts[status] || 0) + 1;
  if (applied && new Date(applied).getTime() >= weekAgo) newThisWeek++;
  const label = `**${txt(p['Company']) || '?'}** – ${txt(p['Role']) || 'role?'}`;
  if (['Interview', 'Assessment', 'Offer'].includes(status)) {
    const na = txt(p['Next Action']);
    active.push(`• ${status}: ${label}${na ? ` → ${na}` : ''} ([open](${pg.url}))`);
  }
  if (p['Needs Review']?.checkbox) review.push(`• ${label} ([open](${pg.url}))`);
}

const order = ['Applied', 'Under Review', 'Assessment', 'Interview', 'Offer', 'Rejected', 'No Response'];
const countLine = order.filter(s => counts[s]).map(s => `${s}: **${counts[s]}**`).join(' · ') || 'No applications yet';
const fields = [
  { name: 'Pipeline', value: countLine },
  { name: 'Applied this week', value: String(newThisWeek), inline: true },
  { name: `Marked no response (>${days}d)`, value: String(ghosted), inline: true },
];
if (active.length) fields.push({ name: 'In progress', value: active.join('\n').slice(0, 1000) });
if (review.length) fields.push({ name: 'Needs review in Notion', value: review.join('\n').slice(0, 1000) });

return [{ json: { discordBody: { embeds: [{ title: '📊 Weekly job search summary', color: 3447003, fields, timestamp: new Date().toISOString() }] } } }];
